import{_ as r,o as e,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2019-03-27:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-03-27:: Ceph Orchestration Meeting","date":"2019-03-27T00:00:00.000Z","updated":"2019-04-10T00:00:00.000Z","tags":["Ceph","Orchestration","Distributed Storage","CRUSH Algorithm","High Availability","Scalability"],"categories":["会议纪要","存储技术","Ceph 文档"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-27_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-03-27_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-03-27_-_-_Ceph_Orchestration_Meeting.md"};function s(a,t,n,p,c,h){return e(),o("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年3月27日</p><p><strong>参会人员</strong>： Tim, Brooke, Matt, Tomica 等</p><p><strong>会议主题</strong>： Ceph Orchestrator 模块版本兼容性及测试问题讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. 版本依赖性问题</strong></p><ul><li>Ceph Orchestrator 模块与外部 orchestrator 存在兼容性问题，可能导致版本依赖性问题。</li><li>例如，Rook Orchestrator 在 Nautilus 首次模块发布版本中与 Ceph Orchestrator 不兼容。</li><li>已知问题：Orchestrator 模块与外部 orchestrator 之间的依赖关系需要解决。</li></ul><p><strong>2. 解决方案讨论</strong></p><ul><li><strong>版本检查</strong>： <ul><li>在 Orchestrator 模型中添加版本检查机制，确保 Orchestrator 模块与外部 orchestrator 版本兼容。</li><li>使用 <code>Ana status 18</code> 方法检查 Orchestrator 模型状态，并警告使用不稳定版本。</li><li>各个模块内部实现版本检查，确保与对应 manager 模块兼容。</li></ul></li><li><strong>测试</strong>： <ul><li>在 Rook CI、DeepSea CI 等环境测试 Orchestrator 模块，确保与外部 orchestrator 版本兼容。</li><li>进行 smoke test 测试 Orchestrator 模块功能。</li><li>在生产环境中，GUI 应防止更改外部 orchestrator 导致的问题。</li></ul></li></ul><p><strong>3. 行动计划</strong></p><ul><li><strong>Tim</strong>： <ul><li>持续跟进 Orchestrator 模块的版本兼容性问题。</li><li>修复相关 bug，并提交 pull request。</li></ul></li><li><strong>Brooke</strong>： <ul><li>研究解决版本依赖问题的方案。</li></ul></li><li><strong>Matt</strong>： <ul><li>在 DeepSea 中部署 Orchestrator 模块，并打印出 IceCozy 和 Ganesha 端点 URL。</li></ul></li><li><strong>Tomica</strong>： <ul><li>解决 Ansible 运行服务的问题，并修复相关 bug。</li></ul></li></ul><p><strong>4. 其他</strong></p><ul><li>Tim 遇到音频连接问题，会议中部分内容可能存在遗漏。</li></ul><p><strong>备注</strong>：</p><ul><li>本次会议讨论了 Ceph Orchestrator 模块的版本兼容性及测试问题，并提出了相应的解决方案和行动计划。</li><li>需要进一步测试和验证解决方案的有效性。</li></ul>',15)])])}const u=r(l,[["render",s]]);export{_ as __pageData,u as default};
